const p = $input.item.json;
if (p.error) throw new Error('API error: ' + JSON.stringify(p.error));
const firstChild = p.children?.data?.[0] || null;
let coverSourceUrl = null;
let coverStrategy = 'CAROUSEL';
if (firstChild) {
  if (firstChild.media_type === 'VIDEO') {
    coverSourceUrl = firstChild.thumbnail_url || null;
    coverStrategy = 'CAROUSEL → filho[0] VIDEO → thumbnail_url do filho';
  } else {
    coverSourceUrl = firstChild.media_url || null;
    coverStrategy = 'CAROUSEL → filho[0] IMAGE → media_url do filho';
  }
}
if (!coverSourceUrl && firstChild?.media_type !== 'VIDEO') {
  coverSourceUrl = p.media_url || null;
  if (coverSourceUrl) coverStrategy += ' → fallback media_url álbum';
}
if (!coverSourceUrl) throw new Error('CAROUSEL sem URL de capa disponível — post_id 18066040568539014');
