const prep   = $('Preparar Download IMAGE').item.json;
const binary = $input.item.binary?.data;
if (!binary) throw new Error('Download IMAGE falhou: sem dados binários');
const mime = binary.mimeType || '';
const size = binary.fileSize || 0;
if (!mime.startsWith('image/')) throw new Error('IMAGE: Content-Type inválido: ' + mime + ' — esperado image/*');
const MAX = 5 * 1024 * 1024;
if (size > MAX) throw new Error('IMAGE: arquivo muito grande: ' + size + ' bytes (máximo 5 MB)');
const extMap = { 'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp', 'image/gif': 'gif' };
const ext = extMap[mime] || 'jpg';
const storagePath = prep.username + '/' + prep.post_id + '.' + ext;
const publicUrl   = $env.SUPABASE_URL + '/storage/v1/object/public/instagram-covers/' + storagePath;
const uploadUrl   = $env.SUPABASE_URL + '/storage/v1/object/instagram-covers/' + storagePath;
return {
  json: {
    post_id:        prep.post_id,
    username:       prep.username,
    media_type:     prep.media_type,
    cover_strategy: prep.cover_strategy,
    mime_type:      mime,
    ext:            ext,
    file_size_bytes: size,
    storage_path:   storagePath,
    public_url:     publicUrl,
    upload_url:     uploadUrl,
    metricas_antes: prep.metricas_antes
  },
  binary: { data: binary }
};

