const upload = $('Verificar Upload IMAGE').item.json;
const resp   = $input.item.json;
// PostgREST com Prefer: return=representation retorna array dos registros atualizados
const rows = Array.isArray(resp) ? resp : (resp.data ? resp.data : [resp]);
if (rows.length === 0) throw new Error('PATCH IMAGE: nenhum registro atualizado — post_id não encontrado na tabela');
if (rows.length > 1)  throw new Error('PATCH IMAGE: ' + rows.length + ' registros atualizados — esperado exatamente 1');
const row = rows[0];
if (row.post_id !== upload.post_id) throw new Error('PATCH IMAGE: post_id retornado (' + row.post_id + ') diverge do esperado (' + upload.post_id + ')');
// Verificar métricas não alteradas
const antes  = upload.metricas_antes;
const campos = ['like_count','comments_count','shares','saved','reach','impressions','views'];
const divergencias = campos.filter(c => String(row[c]) !== String(antes[c]));
return { json: {
  post_id:              upload.post_id,
  username:             upload.username,
  media_type:           upload.media_type,
  cover_strategy:       upload.cover_strategy,
  mime_type:            upload.mime_type,
  ext:                  upload.ext,
  file_size_bytes:      upload.file_size_bytes,
  storage_path:         upload.storage_path,
  public_url:           upload.public_url,
  upload_ok:            upload.upload_ok,
  patch_registros:      rows.length,
  patch_cover_url:      row.cover_url,
  patch_synced_at:      row.cover_synced_at,
  metricas_divergentes: divergencias,
  metricas_ok:          divergencias.length === 0
}};

