    url_publica_ct:     j.url_publica_ct,
    mime_type:          j.mime_type,
    file_size_bytes:    j.file_size_bytes,
    metricas_ok:        j.metricas_ok,
    metricas_divergentes: j.metricas_divergentes
  };
});

return { json: {
  poc_summary: {
    total:          items.length,
    ok:             ok,
    falhou:         items.length - ok,
    metricas_ok:    metricasOk,
    resultado_geral: resultado
  },
  detalhes: detalhes,
  _nota: 'cover_url_storage contém a URL permanente do Supabase Storage. URLs brutas da Meta CDN não aparecem neste relatório.'
}};
